import { Bot, InlineKeyboard, type Context } from 'grammy';
import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { findClient, summary } from './repository.js';
import { buildSummary } from './reports.js';
import type { RpmClubApi, RpmClubClient } from './rpm-club/client.js';
import { managerMenu } from './telegram-menu.js';
import { keepSearchOpen, type SearchState } from './search-state.js';
